#include <stdio.h>
#include <stdlib.h>

typedef struct {
    long long val;
    int f;
} Node;

static Node heap[100005];
static int heap_size = 0;

static inline void swap_nodes(Node *a, Node *b) {
    Node tmp = *a;
    *a = *b;
    *b = tmp;
}

static void push(long long val, int f) {
    heap_size++;
    int i = heap_size;
    heap[i].val = val;
    heap[i].f = f;
    while (i > 1 && heap[i].val < heap[i / 2].val) {
        swap_nodes(&heap[i], &heap[i / 2]);
        i /= 2;
    }
}

static Node pop(void) {
    Node min_node = heap[1];
    heap[1] = heap[heap_size--];
    int i = 1;
    while (2 * i <= heap_size) {
        int left = 2 * i;
        int right = 2 * i + 1;
        int best = left;
        if (right <= heap_size && heap[right].val < heap[left].val) {
            best = right;
        }
        if (heap[i].val > heap[best].val) {
            swap_nodes(&heap[i], &heap[best]);
            i = best;
        } else {
            break;
        }
    }
    return min_node;
}

static int compare_desc(const void *a, const void *b) {
    long long diff = (*(const int *)b) - (*(const int *)a);
    return (diff > 0) - (diff < 0);
}

int T[100005];
int F[100005];

int main(void) {
    int N, M;
    if (scanf("%d %d", &N, &M) != 2) return 0;

    for (int i = 0; i < N; i++) {
        scanf("%d", &T[i]);
    }

    for (int j = 0; j < M; j++) {
        scanf("%d", &F[j]);
    }

    if (M >= N) {
        printf("0\n");
        return 0;
    }

    qsort(T, N, sizeof(int), compare_desc);

    for (int j = 0; j < M; j++) {
        push(F[j], F[j]);
    }

    unsigned long long total_wait = 0;

    for (int i = M; i < N; i++) {
        Node min_node = pop();
        total_wait += (unsigned long long)T[i] * min_node.val;
        push(min_node.val + min_node.f, min_node.f);
    }

    printf("%llu\n", total_wait);

    return 0;
}
